import os
import re

paper_dir = '/home/USER/runs/paper/qwen-h-u1-turns'

# Search for specific function patterns as a single string
patterns = r'(def get_task|def get_puzzles|def get_demos|def get_start|def load_task|def start_puzzle|task_id|puzzle_request)'

def search_in_files(base_dir):
    """Search for function definitions matching patterns"""
    found = []
    for root, dirs, files in os.walk(base_dir):
        # Skip lib/venv directories  
        if 'lib/' in root or 'venv/' in root:
            continue
        for f in files:
            if f.endswith('.py'):
                filepath = os.path.join(root, f)
                try:
                    with open(filepath, 'r') as fh:
                        content = fh.read()
                        matches = re.findall(patterns, content, re.I)
                        if matches:
                            found.append((filepath, matches))
                except:
                    pass
    return found

results = search_in_files(paper_dir)
print(f"Found {len(results)} matches:")
for filepath, matches in results:
    print(f"  File: {filepath}")
    print(f"    Matches: {matches}")

